def list_work_items(project_id, status=None, work_item_type=None, assigned_to=None, tag=None, source=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "list_work_items"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now() + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": _now(),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(project_id, str) or not re.match(r"^azdo_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "project_id must be a valid azdo_prj_ ULID.", field="project_id")

    enum_status = {"new", "active", "resolved", "closed", "removed"}
    enum_source = {"synced", "created_via_api"}
    enum_sort = {"created_at", "updated_at", "ado_work_item_id", "title"}
    enum_order = {"asc", "desc"}

    if status is not None and (not isinstance(status, str) or status not in enum_status):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(enum_status))
    if source is not None and (not isinstance(source, str) or source not in enum_source):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid source.", field="source", allowed=sorted(enum_source))
    if sort is not None and (not isinstance(sort, str) or sort not in enum_sort):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort field.", field="sort", allowed=sorted(enum_sort))
    if order is not None and (not isinstance(order, str) or order not in enum_order):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid order.", field="order", allowed=sorted(enum_order))
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    else:
        limit = 50

    for fld, val in [("work_item_type", work_item_type), ("assigned_to", assigned_to), ("tag", tag), ("cursor", cursor)]:
        if val is not None and not isinstance(val, str):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{fld} must be a string.", field=fld)

    # project exists (and not deleted)
    projects = _load("projects.json")
    prj = next((p for p in projects if p.get("id") == project_id), None)
    if prj is None or prj.get("state") == "deleted":
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    # Cursor decode
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("endpoint") != endpoint or obj.get("project_id") != project_id:
                _log("error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            offset = obj.get("offset", 0)
            if not isinstance(offset, int) or offset < 0:
                _log("error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            # ensure same filters
            expected = obj.get("filters", {})
            current = {
                "status": status,
                "work_item_type": work_item_type,
                "assigned_to": assigned_to,
                "tag": tag,
                "source": source,
                "sort": sort,
                "order": order,
            }
            if expected != current:
                _log("error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Cursor does not match current query parameters.", field="cursor")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Load and filter
    items = _load("work_items.json")
    rows = [w for w in items if w.get("project_id") == project_id]

    # By default exclude removed unless explicitly asked for removed or status filter provided == removed
    if status is None:
        rows = [w for w in rows if w.get("status") != "removed"]
    if status is not None:
        rows = [w for w in rows if w.get("status") == status]
    if work_item_type:
        rows = [w for w in rows if isinstance(w.get("work_item_type"), str) and w.get("work_item_type") == work_item_type]
    if assigned_to:
        rows = [w for w in rows if isinstance(w.get("assigned_to"), str) and w.get("assigned_to") == assigned_to]
    if source:
        rows = [w for w in rows if w.get("source") == source]
    if tag:
        def _has_tag(w):
            t = w.get("tags")
            return isinstance(t, list) and any(isinstance(x, str) and x == tag for x in t)
        rows = [w for w in rows if _has_tag(w)]

    total = len(rows)

    sort_field = sort or "updated_at"
    sort_order = order or "desc"

    def _key(w):
        v = w.get(sort_field)
        if sort_field in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort_field in ("ado_work_item_id",):
            if isinstance(v, int):
                return v
            return -1
        if sort_field == "title":
            if isinstance(v, str):
                return v.lower()
            return ""
        return v

    rows.sort(key=_key, reverse=(sort_order == "desc"))

    page = rows[offset: offset + limit]
    new_offset = offset + len(page)
    has_more = new_offset < total
    next_cursor = None
    if has_more:
        payload = {
            "v": 1,
            "endpoint": endpoint,
            "project_id": project_id,
            "offset": new_offset,
            "filters": {
                "status": status,
                "work_item_type": work_item_type,
                "assigned_to": assigned_to,
                "tag": tag,
                "source": source,
                "sort": sort,
                "order": order,
            },
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok", meta={"returned": len(page), "total": total})

    return {
        "object": "list",
        "data": page,
        "meta": {
            "project_id": project_id,
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort_field,
            "order": sort_order,
        },
    }

def get_work_item(work_item_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_work_item"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _normalize_rows(obj):
        if isinstance(obj, list):
            return [r for r in obj if isinstance(r, dict)]
        if isinstance(obj, dict):
            for k in ("rows", "items", "data", "work_items"):
                v = obj.get(k)
                if isinstance(v, list):
                    return [r for r in v if isinstance(r, dict)]
            if all(isinstance(v, (str, int, float, bool, type(None), list, dict)) for v in obj.values()):
                return [obj]
        return []

    def _append_log(status, error=None, meta=None, credential_id=None):
        logs = _normalize_rows(_load("request_logs.json"))
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
        }
        if isinstance(error, dict):
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs per tool schema, but relax "strictness" per audit defect:
    # If the caller passes a non-matching id, treat it as "not found" rather than validation error,
    # because real services often accept opaque ids and return 404 when they don't exist.
    if not isinstance(work_item_id, str) or work_item_id.strip() == "":
        err = _err("VALIDATION_ERROR", "work_item_id must be a non-empty string.", field="work_item_id")
        _append_log("error", err["error"])
        return err
    work_item_id = work_item_id.strip()
    if not re.match(r"^azdo_wi_[0-9A-HJKMNP-TV-Z]{10,}$", work_item_id):
        items = _normalize_rows(_load("work_items.json"))
        wi = next((w for w in items if w.get("id") == work_item_id), None)
        if wi is None:
            err = _err("NOT_FOUND", "Work item not found.", work_item_id=work_item_id)
            _append_log("error", err["error"])
            return err
        _append_log("ok", meta={"resolved_via": "id_noncanonical"})
        return {"work_item": wi}

    items = _normalize_rows(_load("work_items.json"))
    wi = next((w for w in items if w.get("id") == work_item_id), None)
    if wi is None:
        err = _err("NOT_FOUND", "Work item not found.", work_item_id=work_item_id)
        _append_log("error", err["error"])
        return err

    _append_log("ok", meta={"resolved_via": "id"})
    return {"work_item": wi}

def create_work_item(project_id, work_item_type, title, description=None, assigned_to=None, status=None, area_path=None, iteration_path=None, tags=None, **_extra):
    import json, os, datetime, re, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "create_work_item"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now() + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": _now(),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(project_id, str) or not re.match(r"^azdo_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "project_id must be a valid azdo_prj_ ULID.", field="project_id")

    if not isinstance(work_item_type, str) or not work_item_type.strip():
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "work_item_type is required and must be non-empty.", field="work_item_type")
    if not isinstance(title, str) or not title.strip():
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title is required and must be non-empty.", field="title")

    allowed_status = {"new", "active", "resolved", "closed", "removed"}
    if status is None:
        status = "new"
    if not isinstance(status, str) or status not in allowed_status:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(allowed_status))

    if status not in {"new", "active"}:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Initial status must be 'new' or 'active' when creating via API.", field="status", allowed=["new", "active"])

    for fld, val in [("description", description), ("assigned_to", assigned_to), ("area_path", area_path), ("iteration_path", iteration_path)]:
        if val is not None and not isinstance(val, str):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{fld} must be a string.", field=fld)

    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")

    # Project existence
    projects = _load("projects.json")
    prj = next((p for p in projects if p.get("id") == project_id), None)
    if prj is None or prj.get("state") == "deleted":
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    now = _now()

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        rnd = "".join(random.choice(alphabet) for _ in range(16))
        t = int(datetime.datetime.utcnow().timestamp() * 1000)
        # base32-ish time component
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        return prefix + "".join(reversed(out)) + rnd

    work_items = _load("work_items.json")

    new_row = {
        "id": _gen_ulid_like("azdo_wi_"),
        "project_id": project_id,
        "ado_work_item_id": None,
        "work_item_type": work_item_type.strip(),
        "title": title.strip(),
        "description": description,
        "assigned_to": assigned_to,
        "status": status,
        "area_path": area_path,
        "iteration_path": iteration_path,
        "tags": tags if tags is not None else None,
        "url": None,
        "source": "created_via_api",
        "last_synced_at": None,
        "created_at": now,
        "updated_at": now,
    }

    work_items.append(new_row)
    _save("work_items.json", work_items)

    _log("ok", meta={"work_item_id": new_row["id"], "project_id": project_id})
    return {"object": "work_item", "data": new_row}

