    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("endpoint") != endpoint or obj.get("project_id") != project_id or obj.get("repository_id") != repository_id:
                _log("error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            offset = obj.get("offset", 0)
            if not isinstance(offset, int) or offset < 0:
                _log("error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            expected = obj.get("filters", {})
            current = {
                "status": status,
