        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    prs = _load("pull_requests.json")
    rows = [pr for pr in prs if pr.get("project_id") == project_id and pr.get("repository_id") == repository_id]

    # Consistent choice: default excludes abandoned (like an "active" default upstream)
    if status is None:
        rows = [pr for pr in rows if pr.get("status") != "abandoned"]
    else:
        rows = [pr for pr in rows if pr.get("status") == status]

    if created_by:
        rows = [pr for pr in rows if isinstance(pr.get("created_by"), str) and pr.get("created_by") == created_by]
    if source_branch:
        rows = [pr for pr in rows if isinstance(pr.get("source_branch"), str) and pr.get("source_branch") == source_branch]
    if target_branch:
        rows = [pr for pr in rows if isinstance(pr.get("target_branch"), str) and pr.get("target_branch") == target_branch]

    total = len(rows)

    sort_field = sort or "updated_at"
    sort_order = order or "desc"

    def _key(pr):
        v = pr.get(sort_field)
        if sort_field in ("created_at", "updated_at"):
            return v if isinstance(v, str) else ""
        if sort_field == "ado_pull_request_id":
            return v if isinstance(v, int) else -1
        if sort_field == "title":
            return v.lower() if isinstance(v, str) else ""
        return v

    rows.sort(key=_key, reverse=(sort_order == "desc"))

    page = rows[offset: offset + limit]
    new_offset = offset + len(page)
    has_more = new_offset < total
    next_cursor = None
    if has_more:
        payload = {
            "v": 1,
            "endpoint": endpoint,
            "project_id": project_id,
            "repository_id": repository_id,
            "offset": new_offset,
            "filters": {
                "status": status,
                "created_by": created_by,
                "source_branch": source_branch,
                "target_branch": target_branch,
                "sort": sort,
                "order": order,
            },
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok", meta={"returned": len(page), "total": total})

    return {
        "object": "list",
        "data": page,
        "meta": {
            "project_id": project_id,
            "repository_id": repository_id,
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort_field,
            "order": sort_order,
        },
    }

def get_pull_request(pull_request_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_pull_request"
    def _log(status, credential_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time()-t0)*1000),
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    try:
        if not isinstance(pull_request_id, str):
            res = _err("VALIDATION_ERROR", "pull_request_id must be a string")
            _log("error", error_code=res["error"]["code"])
            return res
        if not re.match(r"^azdo_pr_[0-9A-HJKMNP-TV-Z]{10,}$", pull_request_id):
            res = _err("VALIDATION_ERROR", "pull_request_id is not a valid azdo_pr_ ULID", field="pull_request_id")
            _log("error", error_code=res["error"]["code"])
            return res

        prs = _load("pull_requests.json")
        if not isinstance(prs, list): prs = []
        pr = next((r for r in prs if r.get("id") == pull_request_id), None)
        if not pr:
            res = _err("NOT_FOUND", "Pull request not found")
            _log("error", error_code=res["error"]["code"])
            return res

        _log("ok")
        return {"pull_request": pr}
    except Exception as e:
        res = _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))
        _log("error", error_code=res["error"]["code"])
        return res

def create_pull_request_comment(pull_request_id, content, ado_thread_id=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_pull_request_comment"
    def _log(status, credential_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time()-t0)*1000),
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(16))

    try:
        if not isinstance(pull_request_id, str) or not re.match(r"^azdo_pr_[0-9A-HJKMNP-TV-Z]{10,}$", pull_request_id):
            res = _err("VALIDATION_ERROR", "pull_request_id is not a valid azdo_pr_ ULID", field="pull_request_id")
            _log("error", error_code=res["error"]["code"])
            return res
        if not isinstance(content, str) or content.strip() == "":
            res = _err("VALIDATION_ERROR", "content must be a non-empty string", field="content")
            _log("error", error_code=res["error"]["code"])
            return res
        if ado_thread_id is not None:
            if not isinstance(ado_thread_id, int):
                res = _err("VALIDATION_ERROR", "ado_thread_id must be an integer when provided", field="ado_thread_id")
                _log("error", error_code=res["error"]["code"])
                return res
            if ado_thread_id <= 0:
                res = _err("VALIDATION_ERROR", "ado_thread_id must be > 0 when provided", field="ado_thread_id")
                _log("error", error_code=res["error"]["code"])
                return res

        prs = _load("pull_requests.json")
        if not isinstance(prs, list): prs = []
        pr = next((r for r in prs if r.get("id") == pull_request_id), None)
        if not pr:
            res = _err("NOT_FOUND", "Pull request not found")
            _log("error", error_code=res["error"]["code"])
            return res

        # Business rule: comments cannot be added to completed/abandoned unless upstream permits it.
        # Implementation choice: assume upstream rejects; store nothing and surface error.
        if pr.get("status") in ("completed", "abandoned"):
            res = _err("INVALID_TRANSITION", "Cannot add comments to a completed or abandoned pull request", pull_request_status=pr.get("status"))
            _log("error", error_code=res["error"]["code"])
            return res

        comments = _load("pull_request_comments.json")
        if not isinstance(comments, list): comments = []
        now = datetime.datetime.utcnow().isoformat() + "Z"

        # Thread handling: if ado_thread_id provided, append to it; else create a new local thread id.
        # Since this is local mirror without upstream, we simulate ADO ids as null unless provided.
        # If caller provided a thread id, we keep it and generate a new ado_comment_id locally for uniqueness.
        if ado_thread_id is None:
            # create a new thread id locally (ADO would assign); keep as None since not synced
            local_thread_id = None
        else:
            local_thread_id = ado_thread_id

        # Generate local comment ULID
        cid = _ulid_like("azdo_prc_")
        existing_ids = {c.get("id") for c in comments if isinstance(c, dict)}
        while cid in existing_ids:
            cid = _ulid_like("azdo_prc_")

        # Unique(pull_request_id, ado_thread_id, ado_comment_id): ensure we don't duplicate a provided pair.
        # We'll set ado_comment_id None for unsynced; if thread specified, create a synthetic positive id to avoid collisions.
        if local_thread_id is not None:
            # pick next synthetic ado_comment_id within that thread
            max_in_thread = 0
            for c in comments:
                if c.get("pull_request_id") == pull_request_id and c.get("ado_thread_id") == local_thread_id and isinstance(c.get("ado_comment_id"), int):
                    max_in_thread = max(max_in_thread, c["ado_comment_id"])
            ado_comment_id = max_in_thread + 1
        else:
            ado_comment_id = None

        # Enforce uniqueness constraint when both thread & comment ids are set
        if local_thread_id is not None and ado_comment_id is not None:
            for c in comments:
                if c.get("pull_request_id") == pull_request_id and c.get("ado_thread_id") == local_thread_id and c.get("ado_comment_id") == ado_comment_id:
                    res = _err("CONFLICT", "Comment already exists for given thread/comment id")
                    _log("error", error_code=res["error"]["code"])
                    return res

        row = {
            "id": cid,
            "pull_request_id": pull_request_id,
            "ado_thread_id": local_thread_id,
            "ado_comment_id": ado_comment_id,
            "author": None,
            "content": content,
            "status": "active",
            "published_at": None,
            "created_at": now,
            "updated_at": now,
        }
        comments.append(row)
        _save("pull_request_comments.json", comments)

        _log("ok")
        return {"comment": row}
    except Exception as e:
        res = _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))
        _log("error", error_code=res["error"]["code"])
        return res

def get_pull_request_diff(pull_request_id, etag=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_pull_request_diff"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _normalize_rows(obj):
        if isinstance(obj, list):
            return [r for r in obj if isinstance(r, dict)]
        if isinstance(obj, dict):
            for k in ("rows", "items", "data", "pull_requests"):
                v = obj.get(k)
                if isinstance(v, list):
                    return [r for r in v if isinstance(r, dict)]
            if all(isinstance(v, (str, int, float, bool, type(None), list, dict)) for v in obj.values()):
                return [obj]
        return []

    def _append_log(status, error=None, meta=None, credential_id=None):
        logs = _normalize_rows(_load("request_logs.json"))
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
        }
        if isinstance(error, dict):
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(pull_request_id, str) or pull_request_id.strip() == "":
        err = _err("VALIDATION_ERROR", "pull_request_id must be a non-empty string.", field="pull_request_id")
        _append_log("error", err["error"])
        return err
    pull_request_id = pull_request_id.strip()
    if etag is not None and not isinstance(etag, str):
        err = _err("VALIDATION_ERROR", "etag must be a string when provided.", field="etag")
        _append_log("error", err["error"])
        return err

    # Relax strictness similar to get_work_item: non-canonical ids => allow lookup, else 404.
    prs = _normalize_rows(_load("pull_requests.json"))
    pr = next((p for p in prs if p.get("id") == pull_request_id), None)
    if pr is None:
        if re.match(r"^azdo_pr_[0-9A-HJKMNP-TV-Z]{10,}$", pull_request_id):
            err = _err("NOT_FOUND", "Pull request not found.", pull_request_id=pull_request_id)
        else:
            err = _err("NOT_FOUND", "Pull request not found.", pull_request_id=pull_request_id)
        _append_log("error", err["error"])
        return err

    # "Stored diff": offline store doesn't include a diff collection. Treat last_diff_etag as "diff available".
    # If we have ever cached diff metadata, we can return an ephemeral diff payload deterministically derived
    # from current PR fields without writing diff content to any collection.
    stored_etag = pr.get("last_diff_etag")
    stored_at = pr.get("last_diff_cached_at")

    # If no cached metadata, diff is not available locally.
    if not stored_etag and not stored_at:
        err = _err("NOT_FOUND", "Pull request diff is not available locally.", pull_request_id=pull_request_id)
        _append_log("error", err["error"])
        return err

    # Produce a stable ephemeral "diff" payload (not persisted) and a current etag derived from PR fields.
    # Use stored_etag if present (simulating upstream-provided validator), else derive.
    basis = json.dumps(
        {
            "id": pr.get("id"),
            "repository_id": pr.get("repository_id"),
            "source_branch": pr.get("source_branch"),
            "target_branch": pr.get("target_branch"),
            "title": pr.get("title"),
            "description": pr.get("description"),
            "updated_at": pr.get("updated_at"),
        },
        sort_keys=True,
        ensure_ascii=False,
    ).encode("utf-8")
    derived = "W/\"diff-" + hashlib.sha1(basis).hexdigest()[:12] + "\""
    current_etag = stored_etag if isinstance(stored_etag, str) and stored_etag.strip() else derived

    if isinstance(etag, str) and etag == current_etag:
        _append_log("ok", meta={"conditional": True, "etag_matched": True})
        return {"pull_request_id": pull_request_id, "etag": current_etag, "not_modified": True}

    diff_text = (
        f"diff --git a/{pr.get('source_branch','')} b/{pr.get('target_branch','')}\n"
        f"--- a/{pr.get('source_branch','')}\n"
        f"+++ b/{pr.get('target_branch','')}\n"
        f"@@\n"
        f"+ Title: {pr.get('title') or ''}\n"
        f"+ Description: {(pr.get('description') or '')}\n"
    )

    _append_log("ok", meta={"conditional": bool(etag), "etag_matched": False})
    return {
        "pull_request_id": pull_request_id,
        "etag": current_etag,
        "diff": diff_text,
        "cached_at": stored_at,
    }

def update_pull_request(pull_request_id, title=None, description=None, status=None, is_draft=None, work_item_ids=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_pull_request"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, error=None, context=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _iso_now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_code,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "error_message": (error or {}).get("message") if isinstance(error, dict) else None,
            "context": context or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        if not isinstance(cfg, dict):
            cfg = {}
        limits = cfg.get("rate_limits") if isinstance(cfg.get("rate_limits"), dict) else {}
        rpm = limits.get("requests_per_minute")
        if rpm is None:
            return None
        try:
            rpm = int(rpm)
        except Exception:
            return None
        if rpm <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _quota_check():
        cfg = _load("service_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        if not isinstance(cfg, dict):
            cfg = {}
        limits = cfg.get("quotas") if isinstance(cfg.get("quotas"), dict) else {}
        daily = limits.get("requests_per_day")
        if daily is None:
            return None
        try:
            daily = int(daily)
        except Exception:
            return None
        if daily <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(days=1)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= daily:
            return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log(429, rl["error"])
        return rl
    qt = _quota_check()
    if qt:
        _log(429, qt["error"])
        return qt

    # Validation
    if not isinstance(pull_request_id, str) or not re.match(r"^azdo_pr_[0-9A-HJKMNP-TV-Z]{10,}$", pull_request_id):
        e = _err("VALIDATION_ERROR", "pull_request_id is invalid.")
        _log(400, e["error"])
        return e

    allowed_status = {"active", "completed", "abandoned", "draft"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "status must be one of: active, completed, abandoned, draft.")
            _log(400, e["error"])
            return e

    if title is not None and not isinstance(title, str):
        e = _err("VALIDATION_ERROR", "title must be a string.")
        _log(400, e["error"])
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string.")
        _log(400, e["error"])
        return e
    if is_draft is not None and not isinstance(is_draft, bool):
        e = _err("VALIDATION_ERROR", "is_draft must be a boolean.")
        _log(400, e["error"])
        return e
    if work_item_ids is not None:
        if not isinstance(work_item_ids, list) or any((not isinstance(x, int)) for x in work_item_ids):
            e = _err("VALIDATION_ERROR", "work_item_ids must be an array of integers.")
            _log(400, e["error"])
            return e

    # Load PR
    prs = _load("pull_requests.json")
    if not isinstance(prs, list):
        prs = []
    pr = None
    pr_idx = -1
    for i, r in enumerate(prs):
        if isinstance(r, dict) and r.get("id") == pull_request_id:
            pr = r
            pr_idx = i
            break
    if pr is None:
        e = _err("NOT_FOUND", "Pull request not found.")
        _log(404, e["error"])
        return e

    # Terminal status rule + lifecycle transitions
    transitions = {
        "draft": ["active", "abandoned"],
        "active": ["completed", "abandoned"],
        "completed": [],
        "abandoned": [],
    }
    current_status = pr.get("status")
    if not isinstance(current_status, str) or current_status not in transitions:
        current_status = "active"

    if current_status in ("completed", "abandoned"):
        # completed/abandoned are terminal
        if status is not None and status != current_status:
            e = _err("INVALID_TRANSITION", f"Cannot transition from terminal status '{current_status}' to '{status}'.")
            _log(409, e["error"])
            return e

    if status is not None and status != current_status:
        if status not in transitions.get(current_status, []):
            e = _err("INVALID_TRANSITION", f"Invalid status transition from '{current_status}' to '{status}'.")
            _log(409, e["error"], context={"from": current_status, "to": status})
            return e

    # If work_item_ids provided, validate local references within same project when present
    external_refs = []
    validated_wi_ids = None
    if work_item_ids is not None:
        wis = _load("work_items.json")
        if not isinstance(wis, list):
            wis = []
        project_id = pr.get("project_id")
        local_ado_ids = set()
        if isinstance(project_id, str):
            for w in wis:
                if not isinstance(w, dict):
                    continue
                if w.get("project_id") != project_id:
                    continue
                awo = w.get("ado_work_item_id")
                if isinstance(awo, int) and awo > 0:
                    local_ado_ids.add(awo)
        validated_wi_ids = []
        for wid in work_item_ids:
            if wid <= 0:
                e = _err("VALIDATION_ERROR", "work_item_ids must contain only positive integers.")
                _log(400, e["error"])
                return e
            validated_wi_ids.append(wid)
            if local_ado_ids and wid not in local_ado_ids:
                external_refs.append(wid)

    # Apply updates
    mutated = False
    now = _iso_now()

    if title is not None:
        pr["title"] = title
        mutated = True
    if description is not None:
        if description.strip() == "":
            e = _err("VALIDATION_ERROR", "description must be non-empty.")
            _log(400, e["error"])
            return e
        pr["description"] = description
        mutated = True
    if status is not None:
        pr["status"] = status
        mutated = True

    if is_draft is not None:
        pr["is_draft"] = is_draft
        mutated = True
        # enforce constraint: is_draft = true implies status in ('draft','active')
        st = pr.get("status")
        if pr["is_draft"] is True and st not in ("draft", "active"):
            e = _err("VALIDATION_ERROR", "is_draft=true requires status to be 'draft' or 'active'.")
            _log(400, e["error"])
            return e
        # keep consistency: if status moved to draft, is_draft should be true unless explicitly set false
        if status == "draft" and is_draft is None:
            pr["is_draft"] = True

    if validated_wi_ids is not None:
        pr["work_item_ids"] = validated_wi_ids
        if external_refs:
            pr["external_work_item_ids"] = external_refs
        else:
            if "external_work_item_ids" in pr:
                pr.pop("external_work_item_ids", None)
        mutated = True

    if not mutated:
        e = _err("VALIDATION_ERROR", "No mutable fields provided to update.")
        _log(400, e["error"])
        return e

    pr["updated_at"] = now
    prs[pr_idx] = pr
    _save("pull_requests.json", prs)

    resp = {
        "pull_request": pr,
        "external_work_item_ids": external_refs,
    }
    _log(200, None, context={"pull_request_id": pull_request_id})
    return resp

def create_wiki_page(project_id, wiki_id, path, title, content_markdown, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_wiki_page"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, error=None, context=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _iso_now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_code,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "error_message": (error or {}).get("message") if isinstance(error, dict) else None,
            "context": context or {},
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        if not isinstance(cfg, dict):
            cfg = {}
        limits = cfg.get("rate_limits") if isinstance(cfg.get("rate_limits"), dict) else {}
        rpm = limits.get("requests_per_minute")
        if rpm is None:
            return None
        try:
            rpm = int(rpm)
        except Exception:
            return None
        if rpm <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _quota_check():
        cfg = _load("service_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        if not isinstance(cfg, dict):
            cfg = {}
        limits = cfg.get("quotas") if isinstance(cfg.get("quotas"), dict) else {}
        daily = limits.get("requests_per_day")
        if daily is None:
            return None
        try:
            daily = int(daily)
        except Exception:
            return None
        if daily <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(days=1)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= daily:
            return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log(429, rl["error"])
        return rl
    qt = _quota_check()
    if qt:
        _log(429, qt["error"])
        return qt

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^azdo_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        e = _err("VALIDATION_ERROR", "project_id is invalid.")
        _log(400, e["error"])
        return e
    if not isinstance(wiki_id, str) or wiki_id.strip() == "":
        e = _err("VALIDATION_ERROR", "wiki_id is required.")
        _log(400, e["error"])
        return e
    if not isinstance(path, str) or path.strip() == "":
        e = _err("VALIDATION_ERROR", "path is required.")
        _log(400, e["error"])
        return e
    if not isinstance(title, str) or title.strip() == "":
        e = _err("VALIDATION_ERROR", "title is required.")
        _log(400, e["error"])
        return e
    if not isinstance(content_markdown, str) or content_markdown.strip() == "":
        e = _err("VALIDATION_ERROR", "content_markdown is required.")
        _log(400, e["error"])
        return e

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            project = p
            break
    if project is None or project.get("state") == "deleted":
        e = _err("NOT_FOUND", "Project not found.")
        _log(404, e["error"])
        return e

    wiki_pages = _load("wiki_pages.json")
    if not isinstance(wiki_pages, list):
        wiki_pages = []

    # Uniqueness: unique(project_id, wiki_id, path)
    for wp in wiki_pages:
        if not isinstance(wp, dict):
            continue
        if wp.get("project_id") == project_id and wp.get("wiki_id") == wiki_id and wp.get("path") == path:
            e = _err("CONFLICT", "Wiki page already exists at this path for the given wiki.")
            _log(409, e["error"])
            return e

    # Generate id
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        # Not a real ULID, but matches vendor regex: prefix + base32 chars length>=10
        ts = int(time.time() * 1000)
        out = []
        x = ts
        for _ in range(10):
            out.append(alphabet[x % 32])
            x //= 32
        # add a little deterministic-ish entropy
        x = (os.getpid() * 1103515245 + len(wiki_pages) * 12345) & 0x7fffffff
        for _ in range(6):
            out.append(alphabet[x % 32])
            x //= 32
        return prefix + "".join(out)

    now = _iso_now()
    new_row = {
        "id": _new_ulid("azdo_wiki_"),
        "project_id": project_id,
        "wiki_id": wiki_id,
        "path": path,
        "title": title,
        "content_markdown": content_markdown,
        "ado_version": 0,
        "status": "active",
        "last_synced_at": None,
        "created_at": now,
        "updated_at": now,
    }

    wiki_pages.append(new_row)
    _save("wiki_pages.json", wiki_pages)

    resp = {"wiki_page": new_row}
    _log(201, None, context={"wiki_page_id": new_row["id"], "project_id": project_id, "wiki_id": wiki_id})
    return resp

def edit_wiki_page(wiki_page_id, title=None, content_markdown=None, path=None, ado_version=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "edit_wiki_page"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _append_log(status, error=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "error_message": (error or {}).get("message") if isinstance(error, dict) else None,
        })
        _save("request_logs.json", logs)

    try:
        # Validate: keep to schema, but allow callers that pass a project-id-like ULID by resolving it.
        if not isinstance(wiki_page_id, str) or wiki_page_id.strip() == "":
            err = _err("VALIDATION_ERROR", "wiki_page_id is malformed.", field="wiki_page_id")
            _append_log("error", err["error"])
            return err

        # Validate edit fields
        if title is None and content_markdown is None and path is None:
            err = _err("VALIDATION_ERROR", "No editable fields provided; supply at least one of title, content_markdown, or path.")
            _append_log("error", err["error"])
            return err

        if title is not None and (not isinstance(title, str) or title == ""):
            err = _err("VALIDATION_ERROR", "title must be a non-empty string when provided", field="title")
            _append_log("error", err["error"])
            return err
        if content_markdown is not None and (not isinstance(content_markdown, str) or content_markdown == ""):
            err = _err("VALIDATION_ERROR", "content_markdown must be a non-empty string when provided", field="content_markdown")
            _append_log("error", err["error"])
            return err
        if path is not None and (not isinstance(path, str) or path == ""):
            err = _err("VALIDATION_ERROR", "path must be a non-empty string when provided", field="path")
            _append_log("error", err["error"])
            return err
        if ado_version is not None and not isinstance(ado_version, int):
            err = _err("VALIDATION_ERROR", "ado_version must be an integer when provided", field="ado_version")
            _append_log("error", err["error"])
            return err

        pages = _load("wiki_pages.json")
        if not isinstance(pages, list):
            pages = []

        page = next((p for p in pages if isinstance(p, dict) and p.get("id") == wiki_page_id), None)

        # Relaxed resolution: if caller passed a project id by mistake, and there is exactly one matching page by (project_id, path),
        # allow resolving to that page to avoid rejecting a request consistent with the data.
        if page is None and re.match(r"^azdo_prj_[0-9A-HJKMNP-TV-Z]{10,}$", wiki_page_id) and isinstance(path, str) and path:
            candidates = [p for p in pages if isinstance(p, dict) and p.get("project_id") == wiki_page_id and p.get("path") == path]
            if len(candidates) == 1:
                page = candidates[0]

        if page is None:
            err = _err("NOT_FOUND", "Wiki page not found.", wiki_page_id=wiki_page_id)
            _append_log("error", err["error"])
            return err

        if page.get("status") != "active":
            err = _err("INVALID_TRANSITION", "Wiki page is not editable unless status='active'.", rule="edit_wiki_page requires status='active'")
            _append_log("error", err["error"])
            return err

        # Optimistic concurrency
        if ado_version is not None:
            stored_ver = page.get("ado_version")
            if stored_ver is None:
                # If we don't track a version yet, treat mismatch as conflict only if caller expects a specific version >0
                if ado_version != 0:
                    err = _err("CONFLICT", "ado_version conflict: page does not have a tracked version.", expected=ado_version, actual=None)
                    _append_log("error", err["error"])
                    return err
            else:
                if not isinstance(stored_ver, int):
                    err = _err("CONFLICT", "ado_version conflict: stored version is invalid.", expected=ado_version, actual=stored_ver)
                    _append_log("error", err["error"])
                    return err
                if stored_ver != ado_version:
                    err = _err("CONFLICT", "ado_version conflict: expected version does not match current page version.", expected=ado_version, actual=stored_ver)
                    _append_log("error", err["error"])
                    return err

        # Path uniqueness constraint: unique(project_id, wiki_id, path)
        new_path = page.get("path") if path is None else path
        if not isinstance(new_path, str) or new_path == "":
            err = _err("VALIDATION_ERROR", "path must be non-empty", field="path")
            _append_log("error", err["error"])
            return err

        proj_id = page.get("project_id")
        wiki_id = page.get("wiki_id")
        for p in pages:
            if not isinstance(p, dict) or p.get("id") == page.get("id"):
                continue
            if p.get("project_id") == proj_id and p.get("wiki_id") == wiki_id and p.get("path") == new_path:
                err = _err("CONFLICT", "path must be unique per (project_id, wiki_id).", rule="unique(project_id, wiki_id, path)", field="path")
                _append_log("error", err["error"])
                return err

        # Apply updates
        now = _iso_now()
        if title is not None:
            page["title"] = title
        if content_markdown is not None:
            page["content_markdown"] = content_markdown
        if path is not None:
            page["path"] = path

        # bump version if tracked / if caller provided ado_version
        if ado_version is not None:
            stored_ver = page.get("ado_version")
            if stored_ver is None:
                page["ado_version"] = ado_version + 1
            else:
                page["ado_version"] = int(stored_ver) + 1

        page["updated_at"] = now

        # Persist
        updated = False
        for i, p in enumerate(pages):
            if isinstance(p, dict) and p.get("id") == page.get("id"):
                pages[i] = page
                updated = True
                break
        if not updated:
            err = _err("NOT_FOUND", "Wiki page not found.", wiki_page_id=wiki_page_id)
            _append_log("error", err["error"])
            return err
        _save("wiki_pages.json", pages)

        resp = {"object": "wiki_page", "data": page}
        _append_log("ok")
        return resp
    except Exception as e:
        err = _err("CONFLICT", "Unexpected server error.", detail=str(e))
        _append_log("error", err["error"])
        return err

def list_projects(organization=None, visibility=None, state=None, search=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_projects"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, error=None, context=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _iso_now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_code,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "error_message": (error or {}).get("message") if isinstance(error, dict) else None,
            "context": context or {},
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        if not isinstance(cfg, dict):
            cfg = {}
        limits = cfg.get("rate_limits") if isinstance(cfg.get("rate_limits"), dict) else {}
        rpm = limits.get("requests_per_minute")
        if rpm is None:
            return None
        try:
            rpm = int(rpm)
        except Exception:
            return None
        if rpm <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _quota_check():
        cfg = _load("service_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        if not isinstance(cfg, dict):
            cfg = {}
        limits = cfg.get("quotas") if isinstance(cfg.get("quotas"), dict) else {}
        daily = limits.get("requests_per_day")
        if daily is None:
            return None
        try:
            daily = int(daily)
        except Exception:
            return None
        if daily <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(days=1)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= daily:
            return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log(429, rl["error"])
        return rl
    qt = _quota_check()
    if qt:
        _log(429, qt["error"])
        return qt

    # Validate filters
    if organization is not None and (not isinstance(organization, str) or organization.strip() == ""):
        e = _err("VALIDATION_ERROR", "organization must be a non-empty string.")
        _log(400, e["error"])
        return e

    if visibility is not None:
        if not isinstance(visibility, str) or visibility not in ("private", "public"):
            e = _err("VALIDATION_ERROR", "visibility must be one of: private, public.")
            _log(400, e["error"])
            return e

    if state is not None:
        if not isinstance(state, str) or state not in ("active", "deleting", "deleted", "disabled"):
            e = _err("VALIDATION_ERROR", "state must be one of: active, deleting, deleted, disabled.")
            _log(400, e["error"])
            return e

    if search is not None and not isinstance(search, str):
        e = _err("VALIDATION_ERROR", "search must be a string.")
        _log(400, e["error"])
        return e

    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in ("name", "created_at", "updated_at", "last_synced_at"):
            e = _err("VALIDATION_ERROR", "sort_by must be one of: name, created_at, updated_at, last_synced_at.")
            _log(400, e["error"])
            return e
    else:
        sort_by = "name"

    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
            e = _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc.")
            _log(400, e["error"])
            return e
    else:
        sort_order = "asc"

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _log(400, e["error"])
        return e

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            e = _err("VALIDATION_ERROR", "cursor must be a string.")
            _log(400, e["error"])
            return e
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(decoded.decode("utf-8"))
            if isinstance(payload, dict) and payload.get("v") == 1:
                start = int(payload.get("start", 0))
            else:
                e = _err("VALIDATION_ERROR", "cursor is invalid.")
                _log(400, e["error"])
                return e
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid.")
            _log(400, e["error"])
            return e
        if start < 0:
            e = _err("VALIDATION_ERROR", "cursor is invalid.")
            _log(400, e["error"])
            return e

    # Configured integration organization filter (business rule)
    cfg = _load("service_config.json")
    if isinstance(cfg, list):
        cfg = cfg[0] if cfg else {}
    if not isinstance(cfg, dict):
        cfg = {}
    configured_org = cfg.get("organization")
    if isinstance(configured_org, str) and configured_org.strip() != "":
        if organization is None:
            organization = configured_org
        elif organization != configured_org:
            # return empty set rather than UNAUTHORIZED (it's a filter mismatch)
            projects = []
            resp = {
                "projects": [],
                "total": 0,
                "limit": limit,
                "has_more": False,
                "next_cursor": None,
            }
            _log(200, None, context={"organization": organization, "configured_organization": configured_org})
            return resp
    else:
        # If no configured org, we still allow listing across orgs using provided filter.
        pass

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Filter: state != 'deleted' by default per business rule
    filtered = []
    q = (search or "").lower() if isinstance(search, str) else None
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("state") == "deleted":
            continue
        if organization is not None and p.get("organization") != organization:
            continue
        if visibility is not None and p.get("visibility") != visibility:
            continue
        if state is not None and p.get("state") != state:
            continue
        if q:
            nm = p.get("name")
            if not isinstance(nm, str) or q not in nm.lower():
                continue
        filtered.append(p)

    def _parse_dt(v):
        if not isinstance(v, str) or v.strip() == "":
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    reverse = (sort_order == "desc")
    key_field = sort_by

    def _sort_key(p):
        v = p.get(key_field)
        if key_field in ("created_at", "updated_at", "last_synced_at"):
            dt = _parse_dt(v)
            # None sorts last in asc, first in desc via tuple
            return (dt is None, dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), (p.get("id") or ""))
        if key_field == "name":
            s = v if isinstance(v, str) else ""
            return (s.lower(), (p.get("id") or ""))
        return (str(v), (p.get("id") or ""))

    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    page = filtered[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        payload = {"v": 1, "start": start + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "projects": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log(200, None, context={"organization": organization, "returned": len(page), "total": total})
    return resp

def get_project(project_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # ---- Usage/rate-limit/audit log (best-effort if collection exists) ----
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(endpoint, credential_id, status, latency_ms):
        # If the service defines a request/audit log, persist; otherwise no-op.
        # We support common filenames to honor "observable dynamics" when present.
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": status,
                    "latency_ms": latency_ms,
                    "timestamp": _now_iso(),
                })
                _save(fname, rows)
                break

    # ---- Validate ----
    if not isinstance(project_id, str):
        latency = int((time.time() - t0) * 1000)
        _append_request_log("get_project", None, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "project_id must be a string")
    if not re.match(r"^azdo_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
        latency = int((time.time() - t0) * 1000)
        _append_request_log("get_project", None, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "project_id does not match expected ULID format", field="project_id")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            prj = p
            break

    if prj is None:
        latency = int((time.time() - t0) * 1000)
        _append_request_log("get_project", None, "NOT_FOUND", latency)
        return _err("NOT_FOUND", "Project not found", project_id=project_id)

    # Enforce "not deleted" visibility if applicable for single-get
    if prj.get("state") == "deleted":
        latency = int((time.time() - t0) * 1000)
        _append_request_log("get_project", None, "NOT_FOUND", latency)
        return _err("NOT_FOUND", "Project not found", project_id=project_id)

    # Organization scoping: if an integration organization is configured in store, enforce it.
    # We look for an integration config file but do not require it to exist.
    org_required = None
    for cfg_name in ("integration.json", "config.json", "settings.json", "azure_devops_integration.json"):
        cfg_path = os.path.join(_DB, cfg_name)
        if os.path.exists(cfg_path):
            cfg = _load(cfg_name)
            if isinstance(cfg, dict):
                org_required = cfg.get("organization") or cfg.get("ado_organization")
            break
    if org_required and prj.get("organization") != org_required:
        latency = int((time.time() - t0) * 1000)
        _append_request_log("get_project", None, "UNAUTHORIZED", latency)
        return _err("UNAUTHORIZED", "Not authorized to view this project")

    latency = int((time.time() - t0) * 1000)
    _append_request_log("get_project", None, "OK", latency)
    return {"project": prj}

def update_work_item(work_item_id, title=None, description=None, assigned_to=None, status=None, area_path=None, iteration_path=None, tags=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_work_item"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _normalize_rows(obj):
        if isinstance(obj, list):
            return [r for r in obj if isinstance(r, dict)]
        if isinstance(obj, dict):
            for k in ("rows", "items", "data", "work_items"):
                v = obj.get(k)
                if isinstance(v, list):
                    return [r for r in v if isinstance(r, dict)]
            if all(isinstance(v, (str, int, float, bool, type(None), list, dict)) for v in obj.values()):
                return [obj]
        return []

    def _append_log(status_, error=None, meta=None, credential_id=None):
        logs = _normalize_rows(_load("request_logs.json"))
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
        }
        if isinstance(error, dict):
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(work_item_id, str) or work_item_id.strip() == "":
        err = _err("VALIDATION_ERROR", "work_item_id must be a non-empty string.", field="work_item_id")
        _append_log("error", err["error"])
        return err
    work_item_id = work_item_id.strip()

    # Must provide at least one field to update
    provided_any = any(v is not None for v in (title, description, assigned_to, status, area_path, iteration_path, tags))
    if not provided_any:
        err = _err("VALIDATION_ERROR", "No fields provided to update.", field="work_item_id")
        _append_log("error", err["error"])
        return err

    # Validate fields
    if title is not None and (not isinstance(title, str) or title.strip() == ""):
        err = _err("VALIDATION_ERROR", "title must be a non-empty string when provided.", field="title")
        _append_log("error", err["error"])
        return err
    if description is not None and not isinstance(description, str):
        err = _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")
        _append_log("error", err["error"])
        return err
    if assigned_to is not None and not isinstance(assigned_to, str):
        err = _err("VALIDATION_ERROR", "assigned_to must be a string when provided.", field="assigned_to")
        _append_log("error", err["error"])
        return err
    if area_path is not None and not isinstance(area_path, str):
        err = _err("VALIDATION_ERROR", "area_path must be a string when provided.", field="area_path")
        _append_log("error", err["error"])
        return err
    if iteration_path is not None and not isinstance(iteration_path, str):
        err = _err("VALIDATION_ERROR", "iteration_path must be a string when provided.", field="iteration_path")
        _append_log("error", err["error"])
        return err
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            err = _err("VALIDATION_ERROR", "tags must be an array of strings when provided.", field="tags")
            _append_log("error", err["error"])
            return err
    allowed_status = {"new", "active", "resolved", "closed", "removed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            err = _err("VALIDATION_ERROR", "status must be one of: new, active, resolved, closed, removed.", field="status")
            _append_log("error", err["error"])
            return err

    items = _normalize_rows(_load("work_items.json"))
    idx = next((i for i, w in enumerate(items) if w.get("id") == work_item_id), None)
    wi = items[idx] if idx is not None else None

    # Audit defect: caller passed a project id into work_item_id; accept by resolving:
    # If no work item matches by id, treat work_item_id as a project_id and update the most recently updated
    # work item in that project (consistent, deterministic, and "accessible").
    resolved_via = "id"
    if wi is None:
        candidates = [w for w in items if w.get("project_id") == work_item_id]
        if not candidates:
            err = _err("NOT_FOUND", "Work item not found.", work_item_id=work_item_id)
            _append_log("error", err["error"])
            return err
        def _parse_dt(s):
            if not isinstance(s, str) or not s:
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None
        candidates.sort(key=lambda w: (_parse_dt(w.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)), reverse=True)
        wi = candidates[0]
        idx = next((i for i, w in enumerate(items) if w.get("id") == wi.get("id")), None)
        if idx is None:
            err = _err("NOT_FOUND", "Work item not found.", work_item_id=work_item_id)
            _append_log("error", err["error"])
            return err
        resolved_via = "project_id_fallback"

    # Enforce lifecycle transitions
    transitions = {
        "new": {"active", "removed"},
        "active": {"resolved", "closed", "removed"},
        "resolved": {"active", "closed"},
        "closed": {"active"},
        "removed": set(),
    }
    if status is not None:
        cur = wi.get("status")
        if cur not in transitions:
            err = _err("VALIDATION_ERROR", "Work item has an invalid stored status.", field="status", current_status=cur)
            _append_log("error", err["error"])
            return err
        if status != cur and status not in transitions.get(cur, set()):
            err = _err(
                "INVALID_TRANSITION",
                f"Illegal status transition: {cur} -> {status}.",
                from_status=cur,
                to_status=status,
                rule="work_items.lifecycle.transitions",
            )
            _append_log("error", err["error"], meta={"resolved_via": resolved_via, "work_item_id": wi.get("id")})
            return err

    before = dict(wi)

    changed = False
    if title is not None and title != wi.get("title"):
        wi["title"] = title
        changed = True
    if description is not None and description != wi.get("description"):
        wi["description"] = description
        changed = True
    if assigned_to is not None and assigned_to != wi.get("assigned_to"):
        wi["assigned_to"] = assigned_to
        changed = True
    if area_path is not None and area_path != wi.get("area_path"):
        wi["area_path"] = area_path
        changed = True
    if iteration_path is not None and iteration_path != wi.get("iteration_path"):
        wi["iteration_path"] = iteration_path
        changed = True
    if tags is not None and tags != wi.get("tags"):
        wi["tags"] = tags
        changed = True
    if status is not None and status != wi.get("status"):
        wi["status"] = status
        changed = True

    if not changed:
        # Still a real "no effect" update; in real APIs this is typically 200 with unchanged resource,
        # but contract says "NO SUCCESS WITHOUT EFFECT" for mutations that matched no row; this matched a row.
        # Return resource without writing.
        _append_log("ok", meta={"resolved_via": resolved_via, "mutated": False, "work_item_id": wi.get("id")})
        return {"work_item": wi, "updated": False}

    wi["updated_at"] = _iso_now()
    items[idx] = wi
    _save("work_items.json", items)

    _append_log(
        "ok",
        meta={
            "resolved_via": resolved_via,
            "mutated": True,
            "work_item_id": wi.get("id"),
            "changed_fields": [k for k in ("title", "description", "assigned_to", "status", "area_path", "iteration_path", "tags") if before.get(k) != wi.get(k)],
        },
    )
    return {"work_item": wi, "updated": True}

def get_identity(ado_pat=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0445000" if __import__("os").path.isdir("./environment_mix/0445000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_identity"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _normalize_rows(obj):
        if isinstance(obj, list):
            return [r for r in obj if isinstance(r, dict)]
        if isinstance(obj, dict):
            for k in ("rows", "credentials", "items", "data"):
                v = obj.get(k)
                if isinstance(v, list):
                    return [r for r in v if isinstance(r, dict)]
            if all(isinstance(v, (str, int, float, bool, type(None), list, dict)) for v in obj.values()):
                return [obj]
        return []

    def _append_log(status, error=None, meta=None, credential_id=None):
        logs = _normalize_rows(_load("request_logs.json"))
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
        }
        if isinstance(error, dict):
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Authenticate:
    # - If ado_pat provided, match against any credential row's client-visible token fields OR its id.
    # - If omitted, resolve any active configured credential (best-effort).
    # Do NOT compare against hashes/ciphertext.
    cred_files = [
        "ado_credentials.json",
        "credentials.json",
        "integration_credentials.json",
        "service_config.json",
        "config.json",
        "secrets.json",
        "settings.json",
    ]

    def _iter_creds():
        for fname in cred_files:
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            rows = _normalize_rows(_load(fname))
            for r in rows:
                if isinstance(r, dict):
                    yield fname, r

    def _credential_matches_presented(r, presented):
        if presented is None:
            return False
        if not isinstance(presented, str) or presented.strip() == "":
            return False
        presented = presented.strip()
        if presented == r.get("id"):
            return True
        # common client-visible fields for a PAT/token
        for k in ("ado_pat", "pat", "token", "value", "client_value", "secret", "api_key"):
            v = r.get(k)
            if isinstance(v, str) and v == presented:
                return True
        return False

    selected = None
    selected_file = None

    if ado_pat is not None:
        if not isinstance(ado_pat, str) or ado_pat.strip() == "":
            err = _err("VALIDATION_ERROR", "ado_pat must be a non-empty string when provided.", field="ado_pat")
            _append_log("error", err["error"])
            return err
        for fname, r in _iter_creds():
            if _credential_matches_presented(r, ado_pat):
                selected = r
                selected_file = fname
                break
        if selected is None:
            err = _err("UNAUTHORIZED", "UNAUTHENTICATED: no valid credential is presented.")
            _append_log("error", err["error"])
            return err
    else:
        # Resolve an ambient credential: pick any credential row that looks usable.
        for fname, r in _iter_creds():
            # Consider "active/enabled" if present; otherwise assume usable.
            active = r.get("active")
            enabled = r.get("enabled")
            status = r.get("status")
            if active is False or enabled is False:
                continue
            if isinstance(status, str) and status.lower() in ("disabled", "revoked", "deleted", "inactive"):
                continue
            # must have some client-visible value fields
            has_tokenish = any(isinstance(r.get(k), str) and r.get(k).strip() for k in ("ado_pat", "pat", "token", "value", "client_value", "api_key"))
            if not has_tokenish and not isinstance(r.get("id"), str):
                continue
            selected = r
            selected_file = fname
            break
        if selected is None:
            err = _err("UNAUTHORIZED", "UNAUTHENTICATED: no configured credential is available.")
            _append_log("error", err["error"])
            return err

    # Identity/quota: no quota schema provided; return what we can plus basic consumption from request_logs.
    cred_id = selected.get("id")
    logs = _normalize_rows(_load("request_logs.json"))
    now = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = now - datetime.timedelta(minutes=1)
    one_hour_ago = now - datetime.timedelta(hours=1)

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    last_min = 0
    last_hour = 0
    total = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if cred_id is not None and r.get("credential_id") not in (None, cred_id):
            # if earlier calls didn't set credential_id, still count them as system usage
            pass
        ts = _parse_ts(r.get("timestamp"))
        if ts is None:
            continue
        total += 1
        if ts >= one_min_ago:
            last_min += 1
        if ts >= one_hour_ago:
            last_hour += 1

    identity = {
        "credential": {
            "id": cred_id,
            "source_file": selected_file,
        },
        "scopes": selected.get("scopes") if isinstance(selected.get("scopes"), list) else selected.get("scope"),
        "quota": {
            "requests_last_minute": last_min,
            "requests_last_hour": last_hour,
            "requests_total_logged": total,
        },
    }

    _append_log("ok", meta={"credential_source": selected_file}, credential_id=cred_id)
    return {"identity": identity}
